using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

namespace Oathx.Core
{
    /// <summary>
    /// Controls the Loading and Update panels in Assets/Data/Widgets/Launch/Launch.
    /// Available before the game plugin and UISystem are initialized.
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(RectTransform))]
    public class XLauncher : UIBehaviour
    {
        /// <summary>
        /// Root of the regular loading panel.
        /// </summary>
        [SerializeField]
        private GameObject loading;

        /// <summary>
        /// Root of the resource download panel.
        /// </summary>
        [SerializeField]
        private GameObject update;

        /// <summary>
        /// Status message displayed during regular loading.
        /// </summary>
        [SerializeField]
        private Text loadingText;

        /// <summary>
        /// Progress percentage displayed in the loading panel.
        /// </summary>
        [SerializeField]
        private Text loadingPercent;

        /// <summary>
        /// Additional tip displayed in the loading panel.
        /// </summary>
        [SerializeField]
        private Text tip;

        /// <summary>
        /// Status message displayed during resource downloads.
        /// </summary>
        [SerializeField]
        private Text downloadText;

        /// <summary>
        /// Progress percentage displayed in the download panel.
        /// </summary>
        [SerializeField]
        private Text downloadPercent;

        /// <summary>
        /// RawImage rectangle stretched to represent download progress.
        /// </summary>
        [SerializeField]
        private RectTransform fill;

        /// <summary>
        /// Download progress indicator positioned along the handle area.
        /// </summary>
        [SerializeField]
        private RectTransform handle;

        /// <summary>Optional progress fill for the portrait loading panel.</summary>
        [SerializeField]
        private RectTransform loadingFill;

        /// <summary>Optional progress indicator for the portrait loading panel.</summary>
        [SerializeField]
        private RectTransform loadingHandle;

        /// <summary>
        /// Whether progress updates target the download panel.
        /// </summary>
        private bool downloading;

        /// <summary>
        /// Show the view without resetting its current progress.
        /// </summary>
        public void Show()
        {
            gameObject.SetActive(true);
        }

        /// <summary>
        /// Hide the view while preserving its current state.
        /// </summary>
        public void Hide()
        {
            gameObject.SetActive(false);
        }

        /// <summary>
        /// Keep the launch background visible without loading or download overlays.
        /// </summary>
        public void ShowBackground()
        {
            loading.SetActive(false);
            update.SetActive(false);

            Show();
        }

        /// <summary>
        /// Display the regular loading panel.
        /// </summary>
        /// <param name="message">Initial status message; progress is reset to zero.</param>
        public void ShowLoading(string message = "Loading...")
        {
            downloading = false;

            loading.SetActive(true);
            update.SetActive(false);

            UpdateProgress(0f, message);
        }

        /// <summary>
        /// Display the resource download panel.
        /// </summary>
        /// <param name="message">Initial download message; progress is reset to zero.</param>
        public void ShowUpdate(string message = "Downloading resources...")
        {
            downloading = true;
            
            loading.SetActive(false);
            update.SetActive(true);

            UpdateProgress(0f, message);
        }

        /// <summary>
        /// Set the additional loading tip.
        /// </summary>
        /// <param name="text">Tip text to display.</param>
        public void SetTip(string text)
        {
            tip.text = text;
        }

        /// <summary>
        /// Update the active panel. The prefab uses a RawImage fill, not an Image or Slider.
        /// </summary>
        /// <param name="progress">Normalized progress, clamped to zero through one; NaN becomes zero.</param>
        /// <param name="text">Status message for the active panel.</param>
        /// <returns>True when the active panel has been updated.</returns>
        public bool UpdateProgress(float progress, string text)
        {
            progress = float.IsNaN(progress) ? 0f : Mathf.Clamp01(progress);
            int percent = Mathf.RoundToInt(progress * 100f);
            if (!downloading)
            {
                // Current templates combine the message and percentage in DownloadTips.
                // Retain the separate label when an older prefab still supplies one.
                loadingText.text = loadingPercent ? text : $"{text} ({percent}%)";
                if (loadingPercent) loadingPercent.text = $"({percent}%)";

                if (loadingFill && loadingHandle)
                {
                    ApplyProgress(loadingFill, loadingHandle, progress);
                }

                return true;
            }

            downloadText.text = downloadPercent ? text : $"{text} {percent}%";
            if (downloadPercent) downloadPercent.text = $"{percent}%";
            ApplyProgress(fill, handle, progress);

            return true;
        }

        /// <summary>Applies horizontal progress without changing vertical layout.</summary>
        /// <param name="progressFill">The authored fill rectangle.</param>
        /// <param name="progressHandle">The authored progress marker.</param>
        /// <param name="progress">Normalized progress supplied by the caller.</param>
        private static void ApplyProgress(RectTransform progressFill, RectTransform progressHandle, float progress)
        {
            progressFill.anchorMin = new Vector2(0f, progressFill.anchorMin.y);
            progressFill.anchorMax = new Vector2(progress, progressFill.anchorMax.y);
            progressFill.offsetMin = new Vector2(0f, progressFill.offsetMin.y);
            progressFill.offsetMax = new Vector2(0f, progressFill.offsetMax.y);
            progressHandle.anchorMin = new Vector2(progress, progressHandle.anchorMin.y);
            progressHandle.anchorMax = new Vector2(progress, progressHandle.anchorMax.y);
            progressHandle.anchoredPosition = new Vector2(0f, progressHandle.anchoredPosition.y);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Oathx.Bundle.Assets;
using System.Reflection;
using UnityEngine.Networking;
using System;
using Newtonsoft.Json;
using Oathx.Core.Sdk;
using UnityEngine.Rendering.Universal;
using System.IO;

namespace Oathx.Core
{
    [Serializable]
    public class APIVersion
    {
        /// <summary>
        /// version id
        /// </summary>
        public int id
        { get; set; }

        /// <summary>
        /// current client version
        /// </summary>
        public string version
        { get; set; }

        /// <summary>
        /// runtime platform
        /// </summary>
        public string platform
        { get; set; }

        /// <summary>
        /// version create time
        /// </summary>
        public string createTime
        { get; set; }

        /// <summary>
        /// version update time
        /// </summary>
        public string updateTime
        { get; set; }

        /// <summary>
        /// client auth url
        /// </summary>
        public string authUrl
        { get; set; }

        /// <summary>
        /// hotfix cdn list
        /// </summary>
        public string[] cdns
        { get; set; }

        /// <summary>
        /// client pay url
        /// </summary>
        public string payUrl
        { get; set; }

        /// <summary>
        /// version status
        /// </summary>
        public int status
        { get; set; }
    }

    /// <summary>
    /// remote version info
    /// </summary>
    [Serializable]
    public class AppVersion
    {
        /// <summary>
        /// get version is success
        /// </summary>
        public bool success
        { get; set; }

        /// <summary>
        /// version data
        /// </summary>
        public APIVersion data
        { get; set; }

        /// <summary>
        /// error message
        /// </summary>
        public string message
        { get; set; }

        /// <summary>
        /// error code
        /// </summary>
        public int errorCode
        { get; set; }
    }

    /// <summary>
    /// XApp Main Entry
    /// </summary>
    public class XApp : XMonoSingleton<XApp>
    {
        /// <summary>
        /// The app configure.
        /// </summary>
        [SerializeField]
        private XAppConfigure conf;

        /// <summary>
        /// Is breaking update
        /// </summary>
        [SerializeField]
        private bool isBreaking;

        /// <summary>
        /// The auth URL.
        /// </summary>
        [SerializeField]
        private string authUrl;

        /// <summary>
        /// main camera
        /// </summary>
        [SerializeField]
        private Camera mainCamera;

        /// <summary>
        /// Launch view assigned from the scene's UI hierarchy.
        /// </summary>
        [SerializeField]
        private XLauncher launcher;

        /// <summary>Optional desktop startup size; zero preserves automatic resolution selection.</summary>
        [SerializeField]
        private Vector2Int startupResolution;

        /// <summary>
        /// Hide the launch view when the game UI is ready.
        /// </summary>
        public void HideLaunch()
        {
            if (launcher)
                launcher.Hide();
        }

        /// <summary>
        /// Keep only the launch background visible behind the game UI.
        /// </summary>
        public void ShowLaunchBackground()
        {
            if (launcher)
                launcher.ShowBackground();
        }

        /// <summary>
        /// Whether runtime systems have already been shut down.
        /// </summary>
        private bool runtimeShutdown;

        /// <summary>
        /// Awake is called when the script instance is being loaded
        /// </summary>
        private void Awake()
        {
            instance = this;

            Application.targetFrameRate = 60;
            GameObject.DontDestroyOnLoad(this);

            if (mainCamera)
                GameObject.DontDestroyOnLoad(mainCamera);

#if !UNITY_EDITOR
            // Update to the maximum screen resolution
            UpdateResolution();
#endif

            Debug.Log(System.IO.Path.GetTempPath());
        }

        /// <summary>
        /// Get the XAppConfigure ScriptableObject
        /// </summary>
        /// <returns></returns>
        private IEnumerator Start()
        {
            if (!launcher)
            {
                Debug.LogError("Assign the Launch component to XApp.launcher.", this);
                yield break;
            }

            // show the assigned launch view
            launcher.Show();
            launcher.ShowLoading();

            // load app configure
            var req = Resources.LoadAsync<XAppConfigure>(typeof(XAppConfigure).Name);
            yield return req;

            if (req.isDone)
            {
                // init app configure
                conf = req.asset as XAppConfigure;
                if (conf)
                {
                    ClearLocalEntityArchiveIfNeeded();

                    // init app tracking
                    InitAppTracking();

                    yield return DoCheckAppVersion();
                }
            }
            else
            {
#if UNITY_EDITOR
                Debug.LogError($"load app configure failure");
#endif
            }

            yield return new WaitForEndOfFrame();

            // if current no need to break, startup hotfix assemblies
            if (!isBreaking)
            {
                Startup();
            }
        }

        /// <summary>
        /// Clears local entity archive files when the app configure requests a development reset.
        /// </summary>
        private void ClearLocalEntityArchiveIfNeeded()
        {
            if (!conf || !conf.clearLocalEntityArchiveOnStartup)
                return;

            ClearPersistentDataPath();
        }

        /// <summary>
        /// Deletes local persistent archive files under the app persistent data root.
        /// </summary>
        private void ClearPersistentDataPath()
        {
            string path = Application.persistentDataPath;
            if (string.IsNullOrEmpty(path) || !Directory.Exists(path))
                return;

            DirectoryInfo directory = new DirectoryInfo(path);
            foreach (FileInfo file in directory.GetFiles())
                file.Delete();

#if UNITY_EDITOR
            Debug.Log($"Clear local entity archive path {path}");
#endif
        }

        /// <summary>
        /// Update is called once per frame
        /// </summary>
        private void Update()
        {
            XRes.Update();

            // update plugins
            XPluginManager.GetSingleton().Update(Time.deltaTime);
        }

        /// <summary>
        /// OnDestroy is called when the MonoBehaviour will be destroyed
        /// </summary>
        private void OnDestroy()
        {
            ShutdownRuntime();
        }

        /// <summary>
        /// OnApplicationQuit is called before Unity destroys scene objects.
        /// </summary>
        private void OnApplicationQuit()
        {
            ShutdownRuntime();
        }

        /// <summary>
        /// Shuts down loaded plugins before shared runtime objects are destroyed.
        /// </summary>
        private void ShutdownRuntime()
        {
            if (!runtimeShutdown)
            {
                runtimeShutdown = true;

                // unload all plugin
                XPluginManager.GetSingleton().UnloadAllPlugin();

                // close all coroutine
                XCoroutine.StopAll();
            }
        }

        /// <summary>
        /// Initialize app tracking system, we can use it to track user behavior, such as page view, click event, etc.
        /// </summary>
        private void InitAppTracking()
        {
            var api = new InternalTrackingAPI(conf);
            XAppTracking.GetSingleton().RegisterAPI(api);

            // track init tracking succeed event
            XAppTracking.GetSingleton().Login((succeed, message) => {});
        }

        /// <summary>
        /// Fetch remote version info
        /// </summary>
        /// <returns></returns>
        private IEnumerator DoCheckAppVersion()
        {
            XAppTracking.GetSingleton().Track(TrackingEvent.CheckAppVersion);

            // convert bundle source
            XBundleSource source = XBundleSource.Local;
            switch (conf.bundleSource)
            {
                case AppBundleSource.Local:
                    source = XBundleSource.Local;
                    break;

                case AppBundleSource.Bundle:
                    source = XBundleSource.Bundle;
                    break;
            }

            // initialize hotfix system, we must be initialize it before do update
            XHotfixConfig config = new XHotfixConfig(conf.hotfixDebugEnabled);

            // bundle 自动释放延迟由 XAppConfigure.bundleAutoReleaseTime 控制（默认 60s）：
            // 传 0 会在每次加载后立刻卸载 bundle 壳，下一波加载又被迫重新 LoadFromFile，
            // 造成高频卸载/重载抖动；壳本身只占少量内存，驻留换取加载平稳。
            XRes.Initialize(source, conf.bundleAutoReleaseTime, config);

            if (conf.bundleSource == AppBundleSource.Local)
            {
                launcher.UpdateProgress(1.0f,
                    HotfixStatus.HotfixSucceed.ToString());
                yield break;
            }

            // first, fetch remote version info, we need to do hotfix update base on remote version info
            UnityWebRequest req = UnityWebRequest.Get(conf.VersionURL);
            yield return req.SendWebRequest();

            if (req.result != UnityWebRequest.Result.Success)
            {
#if UNITY_EDITOR
                Debug.LogError($"Fetch remote version from {conf.VersionURL} failed {req.error}");
#endif
            }
            else
            {
                // get remote version info from backup server
                AppVersion appVersion = JsonConvert.DeserializeObject<AppVersion>(req.downloadHandler.text);
                if (appVersion.success)
                {
                    // we need to update server url and pay url
                    conf.UpdateServerURL(appVersion.data.authUrl, appVersion.data.payUrl);

                    // convert remote version info to hotfix version info
                    if (TryConvertRemoteVersion(appVersion, out var remoteVersion))
                    {
                        XAppTracking.GetSingleton().Track(TrackingEvent.DoUpdate);
                        yield return DoUpdate(remoteVersion);
                    }
                }
                else
                {
                    Debug.LogError(req.downloadHandler.text);
                }
            }
        }

        /// <summary>
        /// Try convert remote version info
        /// </summary>
        /// <param name="result"></param>
        /// <param name="remoteVersion"></param>
        /// <returns></returns>
        private bool TryConvertRemoteVersion(AppVersion result, out XHotfixVersion remoteVersion)
        {
            remoteVersion = new XHotfixVersion(result.data.version) {
                payUrl = result.data.payUrl, authUrl = result.data.authUrl, cdns = result.data.cdns, platform = result.data.platform
            };

            return true;
        }

        /// <summary>
        /// Do hotfix update
        /// </summary>
        /// <returns></returns>
        private IEnumerator DoUpdate(XHotfixVersion remoteVersion)
        {
            // if need to do hotfix update, perform hotfix update, must be set hotfix enable in app configure
            if (conf.hotfix)
            {
                yield return XRes.DoUpdate(remoteVersion, (status, progress, message) => {
                    switch (status)
                    {

                        // if start to download hotfix bundles
                        case HotfixStatus.HotfixBundles:
                            launcher.ShowUpdate();
                            break;

                        // if need force update app
                        case HotfixStatus.ForeceUpdate:
                            isBreaking = true;
                            break;

                        // if hotfix update succeed
                        case HotfixStatus.HotfixSucceed:
                            launcher.ShowLoading();
                            break;

                        // update download progress
                        case HotfixStatus.DownloadProgress:
                            launcher.UpdateProgress(progress, message);
                            break;
                    }
                });
            }
            else
            {
                launcher.UpdateProgress(1.0f,
                    HotfixStatus.HotfixSucceed.ToString());
            }
        }

        /// <summary>
        /// Startup hotfix assemblies
        /// </summary>
        private void Startup()
        {
            XAppTracking.GetSingleton().Track(TrackingEvent.RunAssembly);

            // run hotfix assemblys
            Assembly[] assemblys = AppDomain.CurrentDomain.GetAssemblies();
            if (assemblys.Length != 0)
            {
                RunHotfixAssemblys(assemblys);
            }
        }

        /// <summary>
        /// Run hotfix assemblies
        /// </summary>
        /// <param name="appConf"></param>
        /// <param name="assemblys"></param>
        private void RunHotfixAssemblys(Assembly[] assemblys)
        {
            if (assemblys.Length != 0)
            {
                List<Type> types = new List<Type>();
                foreach (Assembly assembly in assemblys)
                {
                    foreach (string typeName in conf.plugins)
                    {
                        var type = assembly.GetType(typeName);
                        if (type != null)
                            types.Add(type);
                    }
                }

                bool succeed = false;

                // load and startup plugins
                foreach (Type type in types)
                {
                    XPlugin plugin = XPluginManager.GetSingleton().LoadPlugin(type);
                    if (plugin != null)
                    {
#if UNITY_EDITOR
                        Debug.Log($"Plugin {type} startup succeed");
#endif
                        succeed = true;

                        plugin.Startup();
                    }
                }

                if (!succeed)
                {
                    Debug.LogError($"No plugin startup succeed, please check your app configure");
                }
            }
        }

        /// <summary>
        /// Applies the authored desktop size or preserves native mobile orientation.
        /// </summary>
        /// <returns>True when a valid output resolution policy is available.</returns>
        private bool UpdateResolution()
        {
            if (startupResolution.x > 0 && startupResolution.y > 0)
            {
                if (!Application.isMobilePlatform)
                {
                    Screen.SetResolution(startupResolution.x, startupResolution.y, false);
                }

                return true;
            }

            int maxHeight = 0;
            int maxWidth = 0;

            foreach (var resolution in Screen.resolutions)
            {
                if (resolution.width >= maxWidth && resolution.height >= maxHeight)
                {
                    maxWidth = resolution.width;
                    maxHeight = resolution.height;
                }
            }

            if (maxWidth <= 0 || maxHeight <= 0)
            {
                return false;
            }

            Screen.SetResolution(maxWidth, maxHeight, true);

            return true;
        }

        /// <summary>
        /// get app configure
        /// </summary>
        /// <returns></returns>
        public XAppConfigure GetAppConfigure()
        {
            return conf;
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="camera"></param>
        /// <returns></returns>
        public bool AddOverlayCamera(Camera camera)
        {
            if (!mainCamera || !camera)
                return false;

            UniversalAdditionalCameraData overlayCamera = camera.GetUniversalAdditionalCameraData();
            overlayCamera.renderType = CameraRenderType.Overlay;

            UniversalAdditionalCameraData baseCamera = mainCamera.GetUniversalAdditionalCameraData();
            baseCamera.cameraStack.Add(camera);

            return true;
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="camera"></param>
        /// <returns></returns>
        public bool RemoveOverlayCamera(Camera camera) 
        {
            if (!mainCamera || !camera)
                return false;

            UniversalAdditionalCameraData mainCameraData = mainCamera.GetUniversalAdditionalCameraData();
            mainCameraData.cameraStack.Remove(camera);
            return true;
        }
    }
}

using Oathx.Core;
using Oathx.Widget;
using UnityEngine;

/// <summary>Initializes the product UI and its local Home system.</summary>
public sealed class GamePlugin : XPlugin, UISender
{
    /// <summary>Initializes the UI resource loader without installing business systems.</summary>
    /// <returns>True when infrastructure is ready.</returns>
    public override bool Install()
    {
        UISystem.GetSingleton().Startup(new ResourceConfigure(this) { loader = new GameUILoader(), cacher = new UIDefaultCacher() });

        return true;
    }

    /// <summary>Starts Home; the system hides Launch only after the scene and widget are ready.</summary>
    /// <returns>True when startup completes.</returns>
    public override bool Startup()
    {
        XApp.GetSingleton().ShowLaunchBackground();
        Load<HomeSystem>();

        return true;
    }

    /// <summary>Releases the UI infrastructure.</summary>
    public override void Shutdown()
    {
        UnloadAll();
        UISystem.GetSingleton().Shutdown();
    }

    /// <summary>Releases plugin registrations; this baseline registers none.</summary>
    public override void Uninstall()
    {
    }

    /// <summary>Dispatches typed UI intent events through the existing plugin dispatcher.</summary>
    /// <param name="request">The request originating from a bound widget.</param>
    /// <returns>True when the request implements the application event contract.</returns>
    public bool Send(IUIRequest request)
    {
        if (!(request is IEvent message))
            return false;

        DispatchEvent(message);

        return true;
    }

    /// <summary>Queues UI intent through the existing application event loop.</summary>
    /// <param name="request">The request to enqueue.</param>
    /// <returns>True when the application accepts the event.</returns>
    public bool Post(IUIRequest request)
    {
        return request is IEvent message && XPluginUtility.PostEvent(message);
    }
}

/// <summary>Loads future widgets through the existing framework resource layer.</summary>
public sealed class GameUILoader : UILoader
{
    /// <summary>Loads a resource by its compile-time type.</summary>
    /// <param name="path">Resource path.</param>
    /// <param name="done">Completion callback.</param>
    /// <returns>The loading coroutine.</returns>
    public Coroutine LoadAsync<T>(string path, System.Action<Object> done) where T : Object
    {
        return Oathx.Bundle.Assets.XRes.LoadAsync<T>(path, done);
    }

    /// <summary>Loads a resource by its runtime type.</summary>
    /// <param name="path">Resource path.</param>
    /// <param name="type">Resource type.</param>
    /// <param name="done">Completion callback.</param>
    /// <returns>The loading coroutine.</returns>
    public Coroutine LoadAsync(string path, System.Type type, System.Action<Object> done)
    {
        return Oathx.Bundle.Assets.XRes.LoadAsync(path, type, done);
    }
}

