using UnityEngine;
using UnityEngine.EventSystems;

/// <summary>Provides local scene inspection without owning building or player state.</summary>
public sealed class HomeSceneCamera : MonoBehaviour
{
    /// <summary>The authored camera used to project pointer movement.</summary>
    [SerializeField]
    private Camera sceneCamera;

    /// <summary>The authored camera handle translated across the town.</summary>
    [SerializeField]
    private Transform cameraHandle;

    /// <summary>Limits presentation movement around the initial focus.</summary>
    [SerializeField]
    private float movementRadius = 45f;

    /// <summary>Initial presentation position, independent of gameplay state.</summary>
    private Vector3 origin;

    /// <summary>Previous screen position during a valid drag.</summary>
    private Vector2 previous;

    /// <summary>Whether a pointer gesture started outside the UI.</summary>
    private bool dragging;

    /// <summary>Captures the serialized camera setup after scene activation.</summary>
    private void Awake()
    {
        if (!sceneCamera || !cameraHandle)
        {
            enabled = false;
            return;
        }

        origin = cameraHandle.position;
    }

    /// <summary>Handles mouse or single-touch scene dragging and mouse-wheel zoom.</summary>
    private void Update()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            if (touch.phase == TouchPhase.Began)
                Begin(touch.position, touch.fingerId);
            else if (touch.phase == TouchPhase.Moved && dragging && Input.touchCount == 1)
                Drag(touch.position);
            else if (touch.phase == TouchPhase.Ended || touch.phase == TouchPhase.Canceled || Input.touchCount > 1)
                dragging = false;

            return;
        }

        if (Input.GetMouseButtonDown(0))
            Begin(Input.mousePosition, -1);
        if (Input.GetMouseButton(0) && dragging)
            Drag(Input.mousePosition);
        if (Input.GetMouseButtonUp(0))
            dragging = false;

        if (!EventSystem.current || !EventSystem.current.IsPointerOverGameObject())
        {
            float distance = Mathf.Clamp(-sceneCamera.transform.localPosition.z - Input.mouseScrollDelta.y * 5f, 100f, 180f);
            sceneCamera.transform.localPosition = new Vector3(0f, 0f, -distance);
        }
    }

    /// <summary>Clears transient input when this scene is unloaded or disabled.</summary>
    private void OnDisable()
    {
        dragging = false;
    }

    /// <summary>Moves the presentation camera using two screen-space points.</summary>
    /// <param name="from">Previous pointer position.</param>
    /// <param name="to">Current pointer position.</param>
    /// <returns>True when both points intersect the town plane.</returns>
    public bool Pan(Vector2 from, Vector2 to)
    {
        if (!sceneCamera || !cameraHandle)
            return false;

        Plane plane = new Plane(Vector3.up, new Vector3(0f, 35.17353f, 0f));
        Ray first = sceneCamera.ScreenPointToRay(from);
        Ray second = sceneCamera.ScreenPointToRay(to);
        if (!plane.Raycast(first, out float firstDistance) || !plane.Raycast(second, out float secondDistance))
            return false;

        Vector3 delta = first.GetPoint(firstDistance) - second.GetPoint(secondDistance);
        Vector3 offset = cameraHandle.position + delta - origin;
        offset.y = 0f;
        cameraHandle.position = origin + Vector3.ClampMagnitude(offset, movementRadius);

        return true;
    }

    /// <summary>Begins a gesture only when its initial pointer is outside UI controls.</summary>
    /// <param name="position">Screen-space pointer position.</param>
    /// <param name="pointerId">Touch identifier or the mouse identifier.</param>
    private void Begin(Vector2 position, int pointerId)
    {
        dragging = !EventSystem.current || !EventSystem.current.IsPointerOverGameObject(pointerId);
        previous = position;
    }

    /// <summary>Projects movement onto a horizontal plane and clamps the camera handle.</summary>
    /// <param name="position">Current screen-space pointer position.</param>
    private void Drag(Vector2 position)
    {
        Pan(previous, position);
        previous = position;
    }


}

using System.Collections;
using Oathx.Core;
using Oathx.Widget;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>Loads the camp scene and hands presentation ownership over from Launch.</summary>
public sealed class HomeSystem : XEventModule
{
    /// <summary>Scene included in the product build settings.</summary>
    private const string scenePath = "Assets/Scenes/Home.unity";

    /// <summary>Invalidates asynchronous callbacks when this system is deactivated.</summary>
    private int generation;

    /// <summary>Prevents overlapping scene transitions.</summary>
    private bool transitioning;

    /// <summary>The latest requested lifecycle state, independent of an in-flight scene operation.</summary>
    private bool requestedActive;

    /// <summary>Starts the scene transition and registers the implemented intents.</summary>
    /// <returns>True when the transition has been requested.</returns>
    public override bool OnActive()
    {
        if (!IsActive())
            return false;

        if (requestedActive)
            return true;

        UnsubscribeAll();
        Subscribe<ReqHomeMap>(request => ShowMap(true));
        Subscribe<ReqHomeCamp>(request => ShowMap(false));
        generation++;
        requestedActive = true;
        RequestTransition();

        return true;
    }

    /// <summary>Invalidates pending work, closes the page and unloads the owned scene.</summary>
    public override void OnDetive()
    {
        generation++;
        requestedActive = false;
        UnsubscribeAll();

        System.Type[] widgets = new System.Type[] {
            typeof(UIHome)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: true);
        RequestTransition();
    }

    /// <summary>Switches between the camp and the implemented map preview.</summary>
    /// <param name="visible">Whether to show the map.</param>
    /// <returns>True when a live Home widget handled the request.</returns>
    public bool ShowMap(bool visible)
    {
        if (!IsActive() || !UISystem.GetSingleton().TryGetWidget<UIHome>(out var widget))
            return false;

        return widget.ShowMap(visible);
    }

    /// <summary>Serializes scene loading and unloading instead of overlapping asynchronous operations.</summary>
    private void RequestTransition()
    {
        if (transitioning)
            return;

        transitioning = true;
        XCoroutine.Run(Reconcile());
    }

    /// <summary>Converges scene and page state to the latest lifecycle request.</summary>
    /// <returns>The serialized transition sequence.</returns>
    private IEnumerator Reconcile()
    {
        try
        {
            while (true)
            {
                int requestGeneration = generation;
                Scene scene = SceneManager.GetSceneByPath(scenePath);
                if (!requestedActive)
                {
                    if (scene.isLoaded)
                        yield return SceneManager.UnloadSceneAsync(scene);

                    if (requestGeneration != generation)
                        continue;

                    yield break;
                }

                if (!scene.isLoaded)
                {
                    yield return SceneManager.LoadSceneAsync(scenePath, LoadSceneMode.Additive);
                    scene = SceneManager.GetSceneByPath(scenePath);
                }

                if (requestGeneration != generation)
                    continue;

                if (!scene.isLoaded)
                {
                    Debug.LogError("MINIWOW_HOME_SCENE_LOAD_FAILED");
                    yield break;
                }

                SceneManager.SetActiveScene(scene);
                bool completed = false;
                bool ready = false;
                if (UISystem.GetSingleton().TryGetWidget<UIHome>(out var existing))
                {
                    ready = existing.ShowMap(false);
                    completed = true;
                }
                else
                {
                    UISystem.GetSingleton().OpenWidget<UIHome>(widget => {
                        completed = true;
                        if (requestGeneration == generation && requestedActive && widget)
                            ready = widget.ShowMap(false);
                    });
                }

                float deadline = Time.realtimeSinceStartup + 20f;
                while (!completed && requestGeneration == generation && Time.realtimeSinceStartup < deadline)
                    yield return null;

                if (requestGeneration != generation)
                    continue;

                if (!ready)
                {
                    System.Type[] widgets = new System.Type[] {
                        typeof(UIHome)
                    };

                    UISystem.GetSingleton().CloseWidget(widgets, immediate: true);
                    Debug.LogError("MINIWOW_HOME_WIDGET_LOAD_FAILED");
                    yield break;
                }

                XApp.GetSingleton().HideLaunch();
                Debug.Log("MINIWOW_HOME_READY");
                yield break;
            }
        }
        finally
        {
            transitioning = false;
        }
    }
}

Shader "Miniwow/RecoveredScene"
{
    Properties
    {
        _MainTex ("Source base texture", 2D) = "white" {}
        _Color ("Source tint", Color) = (1,1,1,1)
        _Cutoff ("Source alpha cutoff", Range(0,1)) = 0.5
        _AlphaClip ("Enable alpha cutoff", Float) = 0
        _SrcBlend ("Source blend", Float) = 1
        _DstBlend ("Destination blend", Float) = 0
        _ZWrite ("Depth writing", Float) = 1
        _Cull ("Source culling", Float) = 2
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            Blend [_SrcBlend] [_DstBlend]
            ZWrite [_ZWrite]
            Cull [_Cull]
            CGPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "UnityCG.cginc"
            sampler2D _MainTex;
            float4 _MainTex_ST;
            fixed4 _Color;
            float _Cutoff;
            float _AlphaClip;
            struct Input { float4 vertex : POSITION; float2 uv : TEXCOORD0; fixed4 color : COLOR; };
            struct Output { float4 position : SV_POSITION; float2 uv : TEXCOORD0; fixed4 color : COLOR; };
            Output Vert(Input value)
            {
                Output result;
                result.position = UnityObjectToClipPos(value.vertex);
                result.uv = TRANSFORM_TEX(value.uv, _MainTex);
                result.color = value.color;
                return result;
            }
            fixed4 Frag(Output value) : SV_Target
            {
                fixed4 color = tex2D(_MainTex, value.uv) * _Color * value.color;
                if (_AlphaClip > 0.5) clip(color.a - _Cutoff);
                return color;
            }
            ENDCG
        }
    }
}

using UnityEngine;

/// <summary>Keeps authored Home controls inside the device safe area.</summary>
[RequireComponent(typeof(RectTransform))]
public sealed class HomeSafeArea : MonoBehaviour
{
    /// <summary>The transform owned by this component.</summary>
    private RectTransform target;

    /// <summary>Last applied physical safe rectangle.</summary>
    private Rect previousArea;

    /// <summary>Last observed physical screen size.</summary>
    private Vector2Int previousSize;

    /// <summary>Initializes the component's own transform and applies current insets.</summary>
    private void OnEnable()
    {
        target = GetComponent<RectTransform>();
        Apply();
    }

    /// <summary>Updates insets after a resolution or orientation change.</summary>
    private void LateUpdate()
    {
        if (previousArea != Screen.safeArea || previousSize.x != Screen.width || previousSize.y != Screen.height)
            Apply();
    }

    /// <summary>Converts physical screen insets into normalized canvas anchors.</summary>
    private void Apply()
    {
        if (Screen.width <= 0 || Screen.height <= 0)
            return;

        previousArea = Screen.safeArea;
        previousSize = new Vector2Int(Screen.width, Screen.height);
        target.anchorMin = new Vector2(previousArea.xMin / Screen.width, previousArea.yMin / Screen.height);
        target.anchorMax = new Vector2(previousArea.xMax / Screen.width, previousArea.yMax / Screen.height);
        target.offsetMin = Vector2.zero;
        target.offsetMax = Vector2.zero;
    }
}

using Oathx.Core;
using Oathx.Widget;

/// <summary>Requests the map without starting an unimplemented battle.</summary>
public sealed class ReqHomeMap : IEvent, IUIRequest
{
    /// <summary>Originating widget registration.</summary>
    public string sourceKey
    { get; set; }
}

/// <summary>Requests a return to the camp presentation.</summary>
public sealed class ReqHomeCamp : IEvent, IUIRequest
{
    /// <summary>Originating widget registration.</summary>
    public string sourceKey
    { get; set; }
}

/// <summary>Owns bindings and local presentation for the Home page.</summary>
[Config("Assets/Data/Widgets/Home/Home.prefab", WidgetLayer.center, cacheWidget: false)]
public sealed class UIHome : UIWidget<VMHome>
{
    /// <summary>Bind each intent once for this widget instance.</summary>
    /// <returns>True after binding the two implemented actions.</returns>
    protected override bool Bind()
    {
        vm.MapClick = Send<ReqHomeMap>;
        vm.ReturnClick = Send<ReqHomeCamp>;
        ShowMap(false);

        return true;
    }

    /// <summary>Switch the local presentation without changing player progression.</summary>
    /// <param name="visible">Whether the map should be visible.</param>
    /// <returns>True when the current widget is bound.</returns>
    public bool ShowMap(bool visible)
    {
        if (!vm)
            return false;

        vm.CampVisible = !visible;
        vm.MapVisible = visible;

        return true;
    }
}

